-- Imported from bulawayo%20province.pdf.
-- Unclear names, phone numbers, and amounts are preserved as marked or blank.
-- Duplicate source numbers are retained with suffixed IDs.
-- Uses the shared protected Burial Society registry table.

on conflict (id) do update set
  source_number = excluded.source_number,
  full_name = excluded.full_name,
  phone = excluded.phone,
  amount_paid = excluded.amount_paid,
  source = excluded.source,
  updated_at = now();
